Item.method_code:
interface Form {
	id: string;
};

interface FormInPackage extends Form {
	name: string;
	keyedName: string;
	packageName: string;
};

const instructUserToUseUpdatePackageAction = async (
	items: FormInPackage[]
	) => {
		if (items.length === 0) {
			return;
		}

	const newLine = '\r\n';
	const errorMessages: string = items
		.map(({ name, keyedName, packageName }) => {
			return getResource(
				'item_methods.package_with_form_already_exists',
				keyedName,
				options.itemTypeName,
				packageName
			)
		})
		.join(newLine);

	if (errorMessages.length == 0) {
		return;
	}

	await alert(
		`${errorMessages}${newLine}${getResource(
			'item_methods.use_update_package_action_message'
		)}`
	);
};

const { itemTypeName, getState } = options;
const state = getState();

const selectedInGridForms = state.grid.selectedRows.reduce(
(filtered: string[], rowId: string) => {
	if(!item.isNew(itemTypeName, rowId))
	{
		filtered.push(rowId);
	}
	return filtered;
}, []);

const response : { formsToAdd: Form[]; formsToUpdate: FormInPackage[] } = await odataFetch('method.FilterFormItemsBeforePackage', {
	method: 'POST',
	body: JSON.stringify({
		ids: selectedInGridForms.toString()
	})
});

if (response.formsToAdd && response.formsToAdd.length > 0) {
	await window.aras.addItemToPackageDef(response.formsToAdd, options.itemTypeName);
}

if (response.formsToUpdate && response.formsToUpdate.length > 0) {
	await instructUserToUseUpdatePackageAction(response.formsToUpdate);
}
